boolean transfer(String from, String to, long amount) {
    while (true) {
        try (AbstractTransaction tx = redis.transaction(false)) {   // one connection, no MULTI yet
            tx.watch(from);
            String v = tx.get(from).get();                           // runs now, on the watched connection
            long balance = v == null ? 0 : Long.parseLong(v);
            if (balance < amount) { tx.unwatch(); return false; }
            tx.multi();
            tx.decrBy(from, amount);                                 // queued
            tx.incrBy(to, amount);
            if (tx.exec() != null) return true;                      // null: 'from' changed, try again
        }
    }
}

